        T = [[0]*N for _ in range(N)]
        for k in range(N):
            if A[k][k] == 0:
                for j in range(N):
                    if j != k:
                        T[k][j] += A[k][j]
                for i in range(N):
                    if i != k:
                        T[i][k] += A[i][k]
