answer:
import sys
import numpy as np

def main():
    data = sys.stdin.read().split()
    N, p = int(data[0]), int(data[1])
    vals = list(map(int, data[2:2 + N * N]))
    A = [vals[i * N:(i + 1) * N] for i in range(N)]

    if p == 2:
        B = np.array([[x if x != 0 else 1 for x in row] for row in A], dtype=np.int64)
        C = (B @ B) % 2
        out = []
        for row in C.tolist():
            out.append(' '.join(str(v % 2) for v in row))
        print('\n'.join(out))
        return

    K = sum(1 for row in A for x in row if x == 0)

    def mul(X, Y):
        lo = Y & 32767
        hi = Y >> 15
        r1 = (X @ hi) % p
        r2 = (X @ lo)
        return ((r1 << 15) + r2) % p

    M = np.array(A, dtype=np.int64) % p
    R = np.eye(N, dtype=np.int64)
    base = M.copy()
    e = p
    while e:
        if e & 1:
            R = mul(R, base)
        base = mul(base, base)
        e >>= 1

    S = [[int(v) for v in row] for row in R.tolist()]

    for a in range(N):
        for b in range(N):
            if A[a][b] == 0:
                if a != b:
                    if p == 3:
                        S[a][b] += A[b][a]
                else:
                    for c in range(N):
                        S[c][a] += A[c][a]
                    for d in range(N):
                        S[a][d] += A[a][d]

    sign = (p - 1) if (K % 2 == 1) else 1
    out = []
    for i in range(N):
        out.append(' '.join(str((S[i][j] * sign) % p) for j in range(N)))
    print('\n'.join(out))

main()
